function validate([graph]) {
  if (!Array.isArray(graph) || graph.length < 2 || graph.length > 15) return 'graph needs 2 to 15 nodes.';
  const n = graph.length;
  const indegree = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    if (!Array.isArray(graph[i])) return 'Each graph[i] is a list of nodes.';
    if (new Set(graph[i]).size !== graph[i].length) return 'The nodes in each graph[i] are distinct.';
    for (const next of graph[i]) {
      if (!Number.isInteger(next) || next < 0 || next >= n) return 'Every edge points to a node from 0 to n - 1.';
      if (next === i) return 'A node cannot have an edge to itself.';
      indegree[next]++;
    }
  }
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  let seen = 0;
  while (queue.length) {
    const node = queue.pop();
    seen++;
    for (const next of graph[node]) if (--indegree[next] === 0) queue.push(next);
  }
  if (seen !== n) return 'The graph must not contain a cycle.';
  return null;
}

