function allPathsSourceTarget(graph) {
  const target = graph.length - 1;
  const paths = [];
  const path = [0];

  function explore(node) {
    if (node === target) {
      paths.push([...path]);
      return;
    }
    for (const next of graph[node]) {
      path.push(next);
      explore(next);
      path.pop();
    }
  }

  explore(0);
  return paths;
}

