function allPathsSourceTarget(graph) {
  // Breadth-first over whole partial paths: every queue entry is a path from 0.
  const n = graph.length, out = [];
  let layer = [[0]];
  while (layer.length) {
    const nextLayer = [];
    for (const p of layer) {
      const last = p[p.length - 1];
      if (last === n - 1) { out.push(p); continue; }
      for (const v of graph[last]) nextLayer.push(p.concat(v));
    }
    layer = nextLayer;
  }
  return out;
}

