function generate(rand, size) {
  const n = size === 'large' ? 15 : 2 + Math.floor(rand() * 7);
  // Pick a topological order; usually 0 comes first and n - 1 last so paths exist.
  const middle = [];
  for (let i = 1; i < n - 1; i++) middle.push(i);
  let order;
  if (size === 'small' && rand() < 0.2) {
    order = [0, ...middle, n - 1];
    for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  } else {
    for (let i = middle.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [middle[i], middle[j]] = [middle[j], middle[i]]; }
    order = [0, ...middle, n - 1];
  }
  const density = size === 'large' ? 0.55 + rand() * 0.45 : 0.15 + rand() * 0.75;
  const graph = Array.from({ length: n }, () => []);
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      if (rand() < density) graph[order[a]].push(order[b]);
  for (const list of graph)
    for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
  return [graph];
}
